package config

import (
	"github.com/amkargar/gonex/config"
	"os"
)

func Load() config.Config {
	address := os.Getenv("HTTP_ADDRESS")

	return config.Config{Address: address, DisableHTTP: os.Getenv("GONEX_DISABLE_HTTP") == "1", DisableOpenAPI: os.Getenv("GONEX_DISABLE_OPENAPI") == "1"}
}

main.go:
package main

import (
	"context"
	"example.com/acme/shop/config"
	"example.com/acme/shop/modules"
	"github.com/amkargar/gonex"
	"log"
	"os"
	"os/signal"
	"syscall"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	a, err := gonex.New(config.Load())
	if err != nil {
		log.Fatal(err)
	}
	if err = a.Register(modules.All()...); err != nil {
		log.Fatal(err)
	}
	if (len(os.Args) == 3 || len(os.Args) == 4) && os.Args[1] == "--gonex-openapi" {
		version := ""
		if len(os.Args) == 4 {
			version = os.Args[3]
		}
		document, err := a.OpenAPIVersion(version)
		if err != nil {
			log.Fatal(err)
		}
		if err = os.WriteFile(os.Args[2], document, 0644); err != nil {
			log.Fatal(err)
		}
		return
	}
	if err = a.Run(ctx); err != nil {
		log.Fatal(err)
	}
}

