package users

import (
	"context"
	"testing"
)

func TestMessage(t *testing.T) {
	s := NewService()
	message, err := s.Message(context.Background())
	if err != nil || message != "users" {
		t.Fatal(message, err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err = s.Message(ctx); err == nil {
		t.Fatal("cancelled request accepted")
	}
}
